<div class="erp-grid"><section class="erp-card"><div class="erp-card-head"><div><h2>Kategori Produk</h2><p>Kelola nama dan gambar kategori aroma.</p></div></div><form method="post" class="erp-form"><input type="hidden" name="action" value="admin_category_save"><input type="hidden" name="csrf" value="<?= e(compliance_csrf()) ?>"><label>Nama kategori<input name="name" maxlength="80" required placeholder="Contoh: Floral"></label><label>Path gambar kategori<input name="image" maxlength="255" placeholder="assets/images/categories/pink.png"></label><button class="erp-btn">Tambah kategori</button></form></section><section class="erp-card erp-wide"><div class="erp-table-wrap"><table><thead><tr><th>Kategori</th><th>Gambar</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $x): ?><tr><td><?= e($x['name']) ?></td><td><?= e($x['image']?:'-') ?></td><td><form method="post"><input type="hidden" name="action" value="admin_category_delete"><input type="hidden" name="csrf" value="<?= e(compliance_csrf()) ?>"><input type="hidden" name="id" value="<?= (int)$x['id'] ?>"><button class="erp-link-danger">Hapus</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></div>
